//! Same runtime, actual synthetic HTTP on both sides, own data consents and
//! native peer decision. No host memory/profile, account/quota or physical IO.
#[path="iterative_memory_driver_tests.rs"]mod iterative_memory;
#[path="received_context_iteration_tests.rs"]mod received_iteration;
use super::*;
use crate::pet_runtime::{model,admission::{Evidence,Review,Payment,Denial},admission_tests,authority::Authority,lease_controller::{Controller,Owned,Validity,dispatcher::{self,Driver,Environment,Phase},memory_test_http_fixture as http,memory_test_stream as stream,memory_test_metadata as metadata,memory_test_run as run},received_request::{Caller,Review as DataReview},store::Store,criteria::NATIVE_MESSAGE_CRITERION,planning::{Catalog,Limits},messages::{ReceivedReference,Receipt},recipe_decisions::{Source,Decision}};
use std::sync::{Arc,atomic::{AtomicBool,Ordering}};
fn configuration()->crate::pet_config::Configuration{let mut c=crate::pet_config::defaults();c.pets.get_mut("ai_lmstudio").unwrap().provider="lmstudio".into();for pet in ["ai_ollama","ai_lmstudio"]{c.pets.get_mut(pet).unwrap().permissions.get_or_insert_default().music=false;}c}
fn settings()->crate::settings::Settings{let mut s=crate::settings::Settings::default();s.active_integrations=vec!["ai_ollama".into(),"ai_lmstudio".into()];s}
fn meta(provider:&str)->Value{if provider=="lmstudio"{json!({"models":[{"type":"llm","key":"fixture-free","publisher":"private-fixture","format":"gguf","size_bytes":1,"loaded_instances":[]}]})}else{metadata()}}
fn evidence(f:&Fixture,g:&Record,server:&crate::local_chat::Server)->Evidence{
 let now=crate::assistant_memory::now();let mut d=admission_tests::descriptor(g,now);if server.id=="lmstudio"{d.binding.engine_binding=Some(crate::local_chat::lmstudio::Catalog::parse(server,&meta("lmstudio")).unwrap().binding("fixture-free").unwrap());}
 let capture=crate::pet_runtime::memory_review::Captured::at_with_authority(&f.catalog(),Some(&f.root.join("authority")),g,server,"fixture-free",now).unwrap();Evidence::from_memory_capture(g,&d,"a".repeat(64),now,false,false,capture).unwrap()
}
fn native(f:&Fixture)->Store{Store::existing_verified(&f.root.join("goals"),&f.root.join("authority")).unwrap().unwrap()}
fn budget(deadline:u64,tools:u16)->crate::pet_runtime::admission::Budget{let mut b=admission_tests::budget();b.deadline_at=deadline;b.max_model_calls=1;b.max_tool_calls=tools;b.max_output_bytes=65_536;b.payment=Payment::LocalOnly;b}
struct Env{server:Option<crate::local_chat::Server>,revoke:Option<PathBuf>,choice:bool}
impl Environment for Env{
 fn capture(&self,_:&Owned)->crate::pet_runtime::model::Result<dispatcher::Capture>{let s=self.server.as_ref().expect("source uses an already sealed result");Ok(dispatcher::Capture{configuration:configuration(),server:crate::local_chat::Server{id:s.id,name:s.name,url:s.url.clone(),key:None},app:None})}
 fn configuration(&self)->crate::pet_runtime::model::Result<crate::pet_config::Configuration>{Ok(configuration())}
 fn peer_configuration(&self)->crate::pet_runtime::model::Result<(crate::pet_config::Configuration,crate::settings::Settings)>{Ok((configuration(),settings()))}
 fn target(&self)->crate::pet_runtime::model::Result<Arc<crate::spotify::goal::Target>>{panic!("correspondence does not acquire Spotify")}
 fn notify(&self,_:&dispatcher::Status){}
 fn decide(&self,s:Source)->Option<Decision>{let p=&s.review()["recipe"]["steps"][0]["envelope"];assert_eq!(p["schemaVersion"],10);assert_eq!(p["plannedData"]["source"]["references"].as_array().unwrap().len(),1);if let Some(path)=&self.revoke{fs::write(path,serde_json::to_vec(&json!({"version":1,"generation":2,"items":[]})).unwrap()).unwrap();assert!(!s.current());return None;}let f=crate::cli_chat::goal_decision_fixture(s);f.panel_answer(self.choice,f.request["goalTarget"].clone()).unwrap();f.decision()}
}
fn source(provider:&'static str,revoke:bool)->(Fixture,Authority,Record,Chat,Option<Receipt>){source_for(provider,revoke,60_000)}
fn source_for(provider:&'static str,revoke:bool,ttl:u64)->(Fixture,Authority,Record,Chat,Option<Receipt>){
 let f=Fixture::new();let main=f.main();let mut spec=Fixture::goal(Context::Unbound).spec;spec.owner=Owner{pet_id:crate::pet_config::pet_id(provider).unwrap().into(),provider:provider.into(),adapter:provider.into(),model_hint:Some("fixture-free".into())};spec.criteria=vec![NATIVE_MESSAGE_CRITERION.into()];f.write(vec![Fixture::record("selected-source-note",&spec.owner.pet_id,None)]);let st=Store::ensure(&f.root.join("goals")).unwrap();let g=st.create(spec,crate::assistant_memory::now()).unwrap().record;let(b,private)=f.prepare(&g,&main,Mode::Dedicated,Some(&[Fixture::selected("selected-source-note")])).unwrap();drop(private);let g=st.mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"selected-context".into(),Action::BindContext{binding:b},crate::assistant_memory::now()).unwrap().record;
 let to=if provider=="ollama"{"ai_lmstudio"}else{"ai_ollama"};let deadline=crate::assistant_memory::now()+ttl;let proposal=json!({"kind":"plan","description":"One derived request","steps":[{"description":"Ask another pet","postcondition":"Local receipt only","operation":{"operationId":"pet.message","version":1,"arguments":{"toPetId":to,"kind":"request","text":"DERIVED_APPROVED_TEXT_ONLY","expiresAt":deadline}}}]}).to_string();
 let(mut server,worker)=http(vec![("application/json",meta(provider).to_string()),("text/event-stream",stream(&proposal,true))],|_|{});server.id=provider;
 let review=Review::prepare_planning_catalog(&g,evidence(&f,&g,&server),budget(deadline,1),Limits{max_rounds:1,max_steps:1,max_output_bytes:2048,no_progress_limit:1},&configuration(),Catalog::PeerCorrespondenceMemoryV1,"source-admit".into(),nonce().unwrap(),crate::assistant_memory::now()).unwrap();let approved=review.approve_with_data(&g,evidence(&f,&g,&server),Some(crate::pet_memory::context_model::GoalConsent::BoundedGoalContext),crate::assistant_memory::now()).unwrap();let a=Authority::ensure(&f.root.join("authority")).unwrap();let cert=a.certify(&approved,&g,crate::assistant_memory::now()).unwrap();let q=st.enqueue_certified(&cert,crate::assistant_memory::now()).unwrap().record;assert_eq!(q.schema_version,49);
 let ctl=Controller::new().unwrap();let p=ctl.prepare_memory_fixture(&q,&f.root.join("authority"),&f.contexts(),&f.catalog(),&main,&evidence(&f,&q,&server),"source-claim".into(),crate::assistant_memory::now(),Arc::new(|_,_,_|Validity::Current)).unwrap();let(r,o)=p.claim(&st,&a,&evidence(&f,&q,&server),crate::assistant_memory::now()).unwrap();let g=r.record;let o=Arc::new(o.unwrap());run(o.plan_once(None,&g,&server,"driver-plan-1",&configuration())).unwrap();let requests=worker.join().unwrap();assert_eq!(requests.len(),2);assert!(requests[1].1["messages"].to_string().contains("PRIVATE_GOAL_MEMORY_SENTINEL"));
 let env=Arc::new(Env{server:None,revoke:revoke.then(||f.catalog()),choice:true});let d=Driver::new(o,Arc::new(native(&f)),env).unwrap();let status=run(d.run()).unwrap();let current=native(&f).read(&g.id,&g.spec.owner.pet_id).unwrap();let receipt=current.generated_plans.last().and_then(|p|a.message_at(&current.admissions[0].spec,current.admissions[0].proof.as_ref().unwrap(),&p.plan_id,&current.plans.iter().find(|x|x.id==p.plan_id).unwrap().steps[0].id).unwrap());if revoke{assert!(receipt.is_none()&&current.completion.is_none());}else{assert_eq!(status.phase,Phase::Completed,"{status:?}");assert_eq!(receipt.as_ref().unwrap().envelope().schema_version,10);a.verify_completed_goal(&current).unwrap();}(f,a,current,main,receipt)
}
// Exercise the same native retained decision used by Tauri, not only the
// underlying certificate. Retry returns immutable DATA, never fresh authority.
struct NativeDataAck{input:crate::pet_runtime::received_request_api::ReceivedGoalPrepareInput,pending:Arc<crate::pet_runtime::received_request_api::native::Pending>,goal:Record,after:u64}
impl NativeDataAck{
 fn assert_preserved(&self,f:&Fixture){
  use crate::pet_runtime::received_request_api::ReceivedGoalConfirmed;
  let st=native(f);let path=f.root.join("goals").join(format!("{}.json",self.goal.id));let before=fs::read(&path).unwrap();
  let ReceivedGoalConfirmed::Created{receipt,execution_authority_granted}=self.pending.choose(false,self.after).expect("retained native ACK after choice/frame/source expiry")else{panic!("immutable existing receipt")};assert!(!execution_authority_granted);assert_eq!(receipt.record.id,self.goal.id);
  let i=&self.input;let existing=if self.goal.spec.received_from.as_ref().unwrap().body.delegation.is_some(){st.existing_funded_request(&i.pet_id,&i.source,&i.request_id,&i.intent,&i.criteria)}else{st.existing_received_request(&i.pet_id,&i.source,&i.request_id,&i.intent,&i.criteria)}.expect("prepare route also resolves durable DATA without source renewal").unwrap();assert_eq!(model::fingerprint(&existing.record).unwrap(),model::fingerprint(&receipt.record).unwrap());
  let changed=if self.goal.spec.received_from.as_ref().unwrap().body.delegation.is_some(){st.existing_funded_request(&i.pet_id,&i.source,&i.request_id,"different intent",&i.criteria)}else{st.existing_received_request(&i.pet_id,&i.source,&i.request_id,"different intent",&i.criteria)};assert!(changed.is_err());assert_eq!(fs::read(path).unwrap(),before);
 }
}
fn native_data_confirm(f:&Fixture,review:DataReview,frame:crate::settings::review::Frame)->NativeDataAck{
 use crate::pet_runtime::{received_request_api::{ReceivedGoalPrepareInput,ReceivedGoalConfirmInput,ReceivedGoalConfirmed,native::Reviews},message_api::native::Origin};
 let p=review.proposal();assert!(matches!(p.schema_version,6|7));let input=ReceivedGoalPrepareInput{pet_id:p.future.owner.pet_id.clone(),source:p.source.reference.clone(),request_id:p.client_request_id.clone(),intent:p.future.intent.clone(),criteria:p.future.criteria.clone()};let origin=Origin{window:crate::HUB_LABEL.into(),frame:frame.clone()};let human=Arc::new(AtomicBool::new(true));let flag=human.clone();let mut reviews=Reviews::default();let ticket=reviews.insert(origin.clone(),input.clone(),review,f.root.join("goals"),f.root.join("authority"),Arc::new(move||flag.load(Ordering::Acquire)),crate::assistant_memory::now()).unwrap();
 let confirm=ReceivedGoalConfirmInput{pet_id:input.pet_id.clone(),source:input.source.clone(),token:ticket.token,approve:true};let other=Origin{window:origin.window.clone(),frame:crate::settings::review::Frame::fixture()};assert!(reviews.lookup(&other,&confirm).is_err());let mut forged=ReceivedGoalConfirmInput{pet_id:confirm.pet_id.clone(),source:confirm.source.clone(),token:confirm.token.clone(),approve:true};forged.source.scope_hash="0".repeat(64);assert!(reviews.lookup(&origin,&forged).is_err());
 let pending=reviews.lookup(&origin,&confirm).unwrap();let ReceivedGoalConfirmed::Created{receipt,execution_authority_granted}=pending.choose(true,crate::assistant_memory::now()).unwrap()else{panic!("native own goal DATA")};assert!(!execution_authority_granted);assert!(receipt.record.admissions.is_empty());
 let ack=NativeDataAck{input,pending,goal:receipt.record,after:p.source.deadline_at+1};ack.assert_preserved(f);human.store(false,Ordering::Release);frame.invalidate_for_test();assert!(reviews.lookup(&origin,&confirm).is_err());ack.assert_preserved(f);ack
}
fn selected(f:&Fixture,main:&Chat,r:&Receipt)->Record{selected_with_memory(f,main,r,None)}
fn selected_with_memory(f:&Fixture,main:&Chat,r:&Receipt,selection:Option<&[crate::pet_memory::context_model::Selected]>)->Record{
 let recipient=&r.envelope().recipient.pet_id;let provider=if recipient=="ai_ollama"{"ollama"}else{"lmstudio"};let mut descriptor=admission_tests::descriptor(&Fixture::goal(Context::Unbound),crate::assistant_memory::now());descriptor.pet_id=recipient.clone();descriptor.binding.provider=Some(provider.into());descriptor.binding.adapter=Some(provider);descriptor.binding.model=Some("fixture-free".into());let frame=crate::settings::review::Frame::fixture();let caller=Caller::capture(crate::pet_runtime::message_api::native::Origin{window:crate::HUB_LABEL.into(),frame:frame.clone()},&descriptor).unwrap();let reference=ReceivedReference::from_receipt(r).unwrap();let review=DataReview::prepare_planned_at(&f.root.join("authority"),&f.catalog(),caller,reference,"own-recipient-data".into(),"Own review of derived peer data".into(),vec!["Semantic outcome needs independent verification".into()],crate::assistant_memory::now()).unwrap();assert_eq!(review.proposal().schema_version,6);let ack=native_data_confirm(f,review,frame);let st=native(f);let g=ack.goal;assert_eq!(g.schema_version,if r.envelope().planned_data.as_ref().is_some_and(|p|p.schema_version==4){59}else if r.envelope().planned_data.as_ref().is_some_and(|p|p.schema_version==3){56}else{50});
 let(binding,private)=crate::pet_runtime::context::prepare_selected_data_fixture(&f.contexts(),&g,main,selection,&f.catalog(),&f.root.join("authority"),true).unwrap();drop(private);assert_eq!(binding.schema_version,8);let g=st.mutate(&g.id,recipient,&g.revision,"own-data-context".into(),Action::BindContext{binding},crate::assistant_memory::now()).unwrap().record;let g=st.mutate(&g.id,recipient,&g.revision,"own-response-task".into(),Action::ProposeTask{description:"Own independently authorized response".into()},crate::assistant_memory::now()).unwrap().record;st.mutate(&g.id,recipient,&g.revision,"own-response-plan".into(),Action::ProposePlan{task_id:g.tasks[0].id.clone(),steps:vec![StepInput{description:"Respond to own instruction".into(),postcondition:"Own artefact, no execution authority".into(),operation:None}]},crate::assistant_memory::now()).unwrap().record
}
fn admit(f:&Fixture,a:&Authority,g:&Record,server:&crate::local_chat::Server,main:&Chat)->(Record,Arc<Owned>){
 let b=budget(g.spec.received_from.as_ref().unwrap().body.source.deadline_at,0);let make=|budget|Review::prepare(g,evidence(f,g,server),budget,nonce().unwrap(),nonce().unwrap(),crate::assistant_memory::now());let denied=make(b.clone()).unwrap();assert_eq!(denied.approve(g,evidence(f,g,server),crate::assistant_memory::now()).err(),Some(Denial::DataConsentRequired));let mut wrong=b.clone();wrong.max_tool_calls=1;assert!(make(wrong).is_err());let review=make(b).unwrap();let approved=review.approve_with_data(g,evidence(f,g,server),Some(crate::pet_memory::context_model::GoalConsent::BoundedGoalContext),crate::assistant_memory::now()).unwrap();assert_eq!(approved.spec().schema_version,22);assert_eq!(approved.spec().memory_data.as_ref().unwrap().schema_version,7);let c=a.certify(&approved,g,crate::assistant_memory::now()).unwrap();let q=native(f).enqueue_certified(&c,crate::assistant_memory::now()).unwrap().record;let ctl=Controller::new().unwrap();let p=ctl.prepare_memory_fixture(&q,&f.root.join("authority"),&f.contexts(),&f.catalog(),main,&evidence(f,&q,server),nonce().unwrap(),crate::assistant_memory::now(),Arc::new(|_,_,_|Validity::Current)).unwrap();let(receipt,o)=p.claim(&native(f),a,&evidence(f,&q,server),crate::assistant_memory::now()).unwrap();(receipt.record,Arc::new(o.unwrap()))
}
#[test]fn selected_memory_iteration_uses_ordinary_own_consent_and_original_shared_authority(){
 for provider in ["ollama","lmstudio"]{
  let f=Fixture::new();let main=f.main();let mut spec=Fixture::goal(Context::Unbound).spec;spec.owner=Owner{pet_id:crate::pet_config::pet_id(provider).unwrap().into(),provider:provider.into(),adapter:provider.into(),model_hint:Some("fixture-free".into())};
  f.write(vec![Fixture::record("selected-iteration-note",&spec.owner.pet_id,None)]);
  let st=Store::ensure(&f.root.join("goals")).unwrap();let g=st.create(spec,crate::assistant_memory::now()).unwrap().record;
  let(b,private)=f.prepare(&g,&main,Mode::Dedicated,Some(&[Fixture::selected("selected-iteration-note")])).unwrap();drop(private);
  let g=st.mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"selected-iteration-context".into(),Action::BindContext{binding:b},crate::assistant_memory::now()).unwrap().record;
  let server=crate::local_chat::Server{id:provider,name:"Selected memory fixture",url:"http://127.0.0.1:19017".into(),key:None};
  let mut b=budget(crate::assistant_memory::now()+60_000,8);b.max_model_calls=4;
  let prepare=||Review::prepare_planning_catalog(&g,evidence(&f,&g,&server),b.clone(),Limits{max_rounds:2,max_steps:4,max_output_bytes:2048,no_progress_limit:2},&configuration(),Catalog::PeerDelegationIterationV1,nonce().unwrap(),nonce().unwrap(),crate::assistant_memory::now());
  let review=prepare().unwrap();assert_eq!(review.approve(&g,evidence(&f,&g,&server),crate::assistant_memory::now()).err(),Some(Denial::DataConsentRequired));
  let approved=prepare().unwrap().approve_with_data(&g,evidence(&f,&g,&server),Some(crate::pet_memory::context_model::GoalConsent::BoundedGoalContext),crate::assistant_memory::now()).unwrap();
  assert_eq!(approved.spec().schema_version,24);assert!(approved.spec().peer_memory_iteration());
  let source=crate::pet_runtime::planned_peer_data::Snapshot::from_spec(approved.spec()).unwrap().unwrap();assert_eq!(source.schema_version,3);assert_eq!(source.references.len(),1);assert_eq!(source.references[0].id,"selected-iteration-note");
  let a=Authority::ensure(&f.root.join("authority")).unwrap();let cert=a.certify(&approved,&g,crate::assistant_memory::now()).unwrap();let queued=st.enqueue_certified(&cert,crate::assistant_memory::now()).unwrap().record;assert_eq!(queued.schema_version,55);assert_eq!(queued.admissions[0].spec.budget,b);
  let grant:Value=serde_json::from_slice(&fs::read(f.root.join("authority").join(format!("{}.json",queued.admissions[0].spec.decision_id))).unwrap()).unwrap();assert_eq!(grant["body"]["schemaVersion"],45);assert_eq!(grant["body"]["peerMemoryPlanning"],serde_json::to_value(source).unwrap());assert_eq!(grant["body"]["delegationPool"],serde_json::to_value(&b).unwrap());assert!(grant["body"].get("budgetUsage").is_none());
 }
}
#[test]fn selected_memory_peer_request_and_recipient_own_r43_response_use_same_runtime_on_both_local_engines(){
 for provider in ["ollama","lmstudio"]{let(f,a,source,main,r)=source(provider,false);let r=r.unwrap();let original=fs::read(f.root.join("authority").join(format!("{}.json",source.admissions[0].spec.decision_id))).unwrap();let own=selected(&f,&main,&r);let recipient=if provider=="ollama"{"lmstudio"}else{"ollama"};let(mut server,http)=http(vec![("application/json",meta(recipient).to_string()),("text/event-stream",stream("Own independent analysis",true))],|_|{});server.id=recipient;let(g,o)=admit(&f,&a,&own,&server,&main);let env=Arc::new(Env{server:Some(server),revoke:None,choice:false});let d=Driver::new(o.clone(),Arc::new(native(&f)),env).unwrap();let status=run(d.run()).unwrap();assert_eq!(status.phase,Phase::AwaitingVerification,"{status:?}");let requests=http.join().unwrap();assert_eq!(requests.len(),2);let body=&requests[1].1;let text=body["messages"].to_string();assert!(text.contains("DERIVED_APPROVED_TEXT_ONLY")&&text.contains("receivedPlannedPeerMemoryData"));for private in ["PRIVATE_GOAL_MEMORY_SENTINEL","selected-source-note",r.envelope().origin.lease_id.as_str(),r.envelope().origin.controller_id.as_str()]{assert!(!text.contains(private));}let done=native(&f).read(&g.id,&g.spec.owner.pet_id).unwrap();assert!(done.completion.is_none());let grant:Value=serde_json::from_slice(&fs::read(f.root.join("authority").join(format!("{}.json",g.admissions[0].spec.decision_id))).unwrap()).unwrap();assert_eq!(grant["body"]["budgetUsage"]["attempts"][0]["inputHash"],model::fingerprint(&(&o.lease().id,"fixture-free",body)).unwrap());assert_eq!(fs::read(f.root.join("authority").join(format!("{}.json",source.admissions[0].spec.decision_id))).unwrap(),original);}
}
#[test]fn source_memory_revocation_while_native_peer_decision_waits_prevents_delivery(){for provider in ["ollama","lmstudio"]{let(_f,_a,g,_main,r)=source(provider,true);assert!(r.is_none()&&g.completion.is_none());}}
#[test]fn recipient_memory_dependency_revocation_after_admission_and_during_metadata_prevents_body(){
 let(f,a,_source,main,r)=source("ollama",false);let own=selected(&f,&main,&r.unwrap());let path=f.catalog();let(mut server,http)=http(vec![("application/json",meta("lmstudio").to_string()),("text/event-stream",stream("must not be accepted",true))],move|_|{fs::write(&path,serde_json::to_vec(&json!({"version":1,"generation":2,"items":[]})).unwrap()).unwrap();});server.id="lmstudio";let(g,o)=admit(&f,&a,&own,&server,&main);assert!(run(o.respond_once(None,&g,&server,"own-no-use-after-revoke",&configuration())).is_err());let requests=http.join().unwrap();assert_eq!(requests.len(),1);assert!(requests.iter().all(|(path,_)|path!="/v1/chat/completions"));assert!(native(&f).read(&g.id,&g.spec.owner.pet_id).unwrap().completion.is_none());
}

#[test]fn planned_received_data_native_ack_survives_actual_ancestor_revocation_without_writes(){
 let(f,_a,_source,_main,r)=source("ollama",false);let r=r.unwrap();let frame=crate::settings::review::Frame::fixture();let review=DataReview::prepare_planned_at(&f.root.join("authority"),&f.catalog(),iterative_memory::caller_in(&r.envelope().recipient.pet_id,frame.clone()),ReceivedReference::from_receipt(&r).unwrap(),"native-replay-revoked".into(),"Own finite data review".into(),vec!["Own verified result".into()],crate::assistant_memory::now()).unwrap();let ack=native_data_confirm(&f,review,frame);
 fs::write(f.catalog(),serde_json::to_vec(&json!({"version":1,"generation":2,"items":[]})).unwrap()).unwrap();ack.assert_preserved(&f);
 assert!(DataReview::prepare_planned_at(&f.root.join("authority"),&f.catalog(),iterative_memory::caller(&r.envelope().recipient.pet_id),ReceivedReference::from_receipt(&r).unwrap(),"fresh-after-revocation".into(),"Own finite data review".into(),vec!["Own verified result".into()],crate::assistant_memory::now()).is_err());
}
